function ledgerCard(m){
  const winner=m.winnerTeam==='a'?m.a:m.b,num=v=>Math.max(0,+v||0),stats=t=>m.playerStats&&m.playerStats[t]||t===m.winnerTeam&&m.stats||{},metrics=t=>{const s=stats(t);return'<dl class="war6-ledger-stats"><div><dt>'+num(s.totalFateGenerated)+'</dt><dd>TOTAL FATE</dd></div><div><dt>+'+num(s.fateDifferential)+'</dt><dd>FATE DIFF.</dd></div><div><dt>'+num(s.consolidations)+'</dt><dd>CONS.</dd></div><div><dt>'+duration(num(s.durationMs))+'</dt><dd>TIME</dd></div></dl>';};
  return'<button class="war6-ledger-entry" onclick="openWarMatchDetail(\''+esc(m.id)+'\')"><header><span>BATTLE '+String(m.number).padStart(2,'0')+'</span><b>'+esc(m.zoneName)+'</b><time>'+new Date(m.completedAt).toLocaleString()+'</time></header><div class="war6-ledger-duel"><article class="team-a">'+avatar(m.a,true)+'<div><span>'+esc(state.teams.a.name)+'</span><b>'+esc(m.a?.name||'Team I')+'</b>'+metrics('a')+'</div></article><div class="war6-ledger-result"><span>OFFICIAL VICTOR</span><i>★</i><b>'+esc(winner?.name||'Unrecorded')+'</b></div><article class="team-b"><div><span>'+esc(state.teams.b.name)+'</span><b>'+esc(m.b?.name||'Team II')+'</b>'+metrics('b')+'</div>'+avatar(m.b,true)+'</article></div><footer>'+ (m.forfeitSweep?'<em class="war-ledger-forfeit">Match Forfeited</em>':'') +'<span>AFTER-ACTION FILE</span><b>'+(m.replay?'FULL REPLAY SECURED':'STAT REPORT ONLY')+'</b><i>OPEN DOSSIER →</i></footer></button>';
}
function dispatchRow(m,i){return'<button class="war3-dispatch" onclick="openWarMatchDetail(\''+esc(m.id)+'\')"><span class="war3-dispatch-no">'+String(i+1).padStart(2,'0')+'</span><div class="war3-dispatch-front"><small>'+esc(m.zoneName)+'</small><b>'+esc(m.mapCode)+'</b><time>'+new Date(m.completedAt).toLocaleString()+'</time></div><div class="war3-dispatch-combatants">'+avatar(m.a,true)+'<span><b>'+esc(m.a?.name||'Team I')+'</b><i>AGAINST</i><b>'+esc(m.b?.name||'Team II')+'</b></span>'+avatar(m.b,true)+'</div><strong><i>★</i>'+esc(m.winnerTeam==='a'?m.a?.name:m.b?.name)+'<small>VICTOR</small></strong><em>'+(m.replay?'REPLAY SECURED':'REPORT ONLY')+' →</em></button>';}
function matchPanel(){const rows=allMatches().slice(0,50),fronts=new Set(rows.map(x=>x.zoneId)).size,replays=rows.filter(x=>x.replay).length,latest=rows[0];return'<section class="war3-dispatches"><aside class="war3-dispatch-brief"><span>OPERATIONS ROOM</span><h2>Battle<br>Dispatches</h2><div class="war3-radio-mark">'+dispatchIcon()+'</div><dl><div><dt>'+rows.length+'</dt><dd>REPORTS</dd></div><div><dt>'+fronts+'</dt><dd>FRONTS</dd></div><div><dt>'+replays+'</dt><dd>REPLAYS</dd></div></dl><p>LATEST SIGNAL<br><b>'+(latest?esc(latest.zoneName):'NO CONTACT')+'</b></p></aside><main class="war3-dispatch-board"><header><div><span>INCOMING FIELD REPORTS</span><h3>'+(rows.length?'Most recent engagements':'Awaiting first engagement')+'</h3></div><button onclick="closeWarDrawer()">×</button></header><div class="war3-dispatch-list">'+(rows.length?rows.map(dispatchRow).join(''):'<div class="war3-dispatch-empty"><b>NO DISPATCHES RECEIVED</b><span>Battle reports will be pinned here as each front resolves.</span></div>')+'</div></main></section>';}
