function zoneHistoryPanel(){const zones=viewedWarZones(),z=zones.find(x=>x.id===selectedZoneId)||zones[0],m=meta(z),s=score(z),rows=(z.matches||[]).map((match,i)=>({...match,zoneId:z.id,zoneName:m.name,mapCode:viewedWarMapCode(),a:z.a,b:z.b,number:i+1})),longName=String(m.name||'').length>15?' class="war5-long-zone-name"':'';return'<section class="war2-zone-history"><header><img class="war5-history-landscape" src="'+landscapeArt(z.landscape||{})+'" alt="" onerror="this.style.display=\'none\'"><button class="back" onclick="openWarZone(\''+z.id+'\')">‹</button><div'+longName+'><span>ZONE '+m.no+' · MATCHUP DOSSIER</span><h2>'+esc(m.name)+'</h2></div><button onclick="closeWarDrawer()">×</button></header><div class="war2-zone-history-score"><article class="team-a">'+avatar(z.a,true)+'<div><span>'+esc(state.teams.a.name)+'</span><b>'+esc(z.a?.name||'Open post')+'</b><em>'+s.a+' Stars Contributed</em></div></article><div class="war2-ledger-tally"><span class="war2-ledger-score"><i>'+s.a+'</i><small>CURRENT SCORE</small><i>'+s.b+'</i></span><b>'+s.played+'/5</b><span>BATTLES CONDUCTED</span></div><article class="team-b"><div><span>'+esc(state.teams.b.name)+'</span><b>'+esc(z.b?.name||'Open post')+'</b><em>'+s.b+' Stars Contributed</em></div>'+avatar(z.b,true)+'</article></div><div class="war2-zone-history-facts"><span><b>'+esc(z.landscape?.shortName||'Classified')+'</b>Fixed landscape</span><span><b>'+s.a+'–'+s.b+'</b>Current score</span><span><b>'+Math.max(0,5-s.played)+'</b>Battles remaining</span><span><b>'+esc(s.bonus?state.teams[s.bonus].name:'Unsettled')+'</b>Front control</span></div><div class="war2-zone-history-list">'+(rows.length?rows.map(ledgerCard).join(''):'<div class="war2-empty"><b>No battles conducted</b><span>This dossier will populate after the first matchup.</span></div>')+'</div></section>';}
