function banPanel(z,mine){if(!mine||mine.zone.id!==z.id)return'';const t=mine.team,chosen=z.bans[t],q=banSearch.toLowerCase(),list=cards().filter(c=>!q||String(c.name||'').toLowerCase().includes(q)||String(c.id).includes(q)).slice(0,120);return'<section class="war2-ban-editor"><header><div><span>'+esc(state.teams[t].name)+' · '+chosen.length+'/3</span><h2>Ban three cards</h2></div><button onclick="closeWarDrawer()">×</button></header><p>Your opponent cannot queue with a selected card in the next match.</p><input type="search" value="'+esc(banSearch)+'" placeholder="Search cards" oninput="searchWarBanCards(this.value)"><div class="war2-card-grid">'+list.map(c=>'<button class="'+(chosen.includes(String(c.id))?'selected':'')+'" onclick="toggleWarBanCard(\''+z.id+'\',\''+esc(c.id)+'\')"><span>#'+esc(c.id)+'</span><b>'+esc(c.name)+'</b><em>'+esc(c.type||c.aff||'Card')+'</em></button>').join('')+'</div><footer><span>'+(chosen.length===3?'Ready to lock':'Select '+(3-chosen.length)+' more')+'</span><button onclick="lockWarBans(\''+z.id+'\')" '+(chosen.length===3?'':'disabled')+'>Lock bans</button></footer></section>';}
function rulesPanel(){return'<section class="war3-rules"><header><div><span>SUPREME COMMAND · FIELD MANUAL</span><h2>Warfront Rules</h2></div><button onclick="closeWarDrawer()">×</button></header><div class="war3-rules-lead"><b>TAKE THE FRONTS. WIN THE WAR.</b><span>Two alliances deploy five commanders across five fixed battlefields.</span></div><main>'+[['01','DEPLOYMENT','Choose either alliance and claim one open command post for the current event.'],['02','FRONT BATTLES','Each front is a best-of-five series. Every match victory awards one Battle Star to its winner.'],['03','FRONT CONTROL','The commander with the most victories after five battles controls that front. A forfeit concedes the front 0–5.'],['04','COMMENDATIONS','Three campaign distinctions award two additional stars each for Fate differential, fastest victory, and consolidations.'],['05','VICTORY','The alliance with the most total Battle and Commendation Stars when the timer expires wins the Warfront.'],['06','AFTER ACTION','The final tactical map and complete report remain available for 24 hours after the campaign ends.']].map(x=>'<article><i>'+x[0]+'</i><div><b>'+x[1]+'</b><p>'+x[2]+'</p></div></article>').join('')+'</main><footer>CHALLENGER DECKS · 3× ELO · 3× XP · 3× DROPS</footer></section>';}
function drawerHtml(mine){if(!drawer)return'';const zones=viewedWarZones(),z=zones.find(x=>x.id===selectedZoneId)||zones[2],body=drawer==='zone'?zonePanel(z,mine):drawer==='zone-history'?zoneHistoryPanel():drawer==='rules'?rulesPanel():drawer==='awards'?awardPanel():drawer==='archive'?archivePanel():drawer==='record'?liveRecordPanel():drawer==='matches'?matchPanel():drawer==='match-detail'?matchDetailPanel():drawer==='replay'?replayPanel():drawer==='summary'&&state.lastResult?recordPanel(state.lastResult):banPanel(z,mine);return'<div class="war2-drawer-shade" onclick="closeWarDrawer()"></div><aside class="war2-drawer">'+body+'</aside>';}
function warRankBadge(p){const elo=Math.max(0,+p?.elo||600);try{if(typeof renderRankBadge==='function')return renderRankBadge(elo,'sm');}catch(e){}let name='Footman';try{if(typeof getRank==='function')name=getRank(elo)?.name||name;}catch(e){}return'<span class="war2-rank-fallback"><i>◆</i>'+esc(name)+'</span>';}
function briefingRoster(team){const rows=state.zones.map(z=>({zone:z,player:z[team]}));return'<div class="war2-brief-roster">'+rows.map((x,i)=>{const p=x.player,m=meta(x.zone),elo=p?.elo!=null&&Number.isFinite(Number(p.elo))?Math.max(0,Number(p.elo)):null;return'<article class="'+(p?'filled':'empty')+'"><div class="war2-commander-number">0'+(i+1)+'</div>'+avatar(p)+'<div class="war2-commander-copy"><div class="war2-commander-identity"><b>'+esc(p?.name||'Open command post')+'</b><em>'+(p?(elo===null?'RATING UNAVAILABLE':elo+' ELO'):'AWAITING DEPLOYMENT')+'</em></div><div class="war2-commander-meta"><span>'+esc(m.name)+'</span><i>COMMAND POST</i></div></div></article>';}).join('')+'</div>';}
function briefing(mine,count,t,live){const aCount=state.zones.filter(z=>z.a).length,bCount=state.zones.filter(z=>z.b).length,canChoose=!mine&&state.status==='enrollment';return'<section class="war2-briefing"><header><div><span>CHALLENGER CAMPAIGN · '+esc(state.mapCode)+'</span><h1>WARFRONT</h1><p>Two alliances. Five fronts. Twenty-five battles decide the campaign.</p></div><nav><button onclick="openWarAchievements()">Commendations</button><button onclick="openWarMatches()">Recent matches</button><button onclick="openWarRecord()">War record</button><button onclick="openWarArchive()">Archive · '+state.archives.length+'</button></nav></header><div class="war2-brief-score"><article class="team-a"><span>'+esc(state.teams.a.name)+'</span><b>'+t.a+'</b><em>'+t.match.a+' BATTLE STARS · '+t.award.a+' COMMENDATION STARS</em></article><div><span>'+(live?'WAR ENDS IN':'MOBILIZATION')+'</span><b id="war-event-clock">'+(live?clock(state.endsAt-Date.now()):count+' / 10')+'</b><em>'+(live?'CAMPAIGN ACTIVE':'COMMANDERS READY')+'</em></div><article class="team-b"><span>'+esc(state.teams.b.name)+'</span><b>'+t.b+'</b><em>'+t.match.b+' BATTLE STARS · '+t.award.b+' COMMENDATION STARS</em></article></div><div class="war2-brief-teams"><section class="team-a"><header><div><span>ALLIANCE I</span><h2>'+esc(state.teams.a.name)+'</h2></div><b>'+aCount+'/5</b></header>'+briefingRoster('a')+'</section><section class="team-b"><header><div><span>ALLIANCE II</span><h2>'+esc(state.teams.b.name)+'</h2></div><b>'+bCount+'/5</b></header>'+briefingRoster('b')+'</section></div><footer><div class="war2-brief-modifiers"><span>WARFRONT MULTIPLIERS</span><b><i>3×</i> ELO <i>3×</i> XP <i>3×</i> DROPS</b></div><div class="war2-allegiance"><span>EVENT ALLIANCE</span><b>Choose either alliance for this deployment.</b></div>'+(canChoose?'<div class="war2-brief-choose"><button class="team-a '+(selectedTeam==='a'?'active':'')+'" '+(aCount>=5?'disabled':'')+' onclick="selectWarEventTeam(\'a\')">JOIN COMINTERN</button><button class="team-b '+(selectedTeam==='b'?'active':'')+'" '+(bCount>=5?'disabled':'')+' onclick="selectWarEventTeam(\'b\')">JOIN THE FREE WORLD</button></div>':'<strong>'+(mine?'Assigned to '+esc(meta(mine.zone).name):live?'Deployment closed':'Awaiting commanders')+'</strong>')+'<button class="war2-enter-map" onclick="openWarTacticalMap()">ENTER TACTICAL MAP <i>→</i></button></footer></section>';}
function tacticalMap(mine,count,t,live){return'<header class="war2-topbar"><button class="war2-brief-back" onclick="openWarBriefing()">‹ BRIEFING</button><div class="war2-title"><span>TACTICAL</span><h1>MAP</h1></div><div class="war2-score team-a"><span>'+esc(state.teams.a.name)+'</span><b>'+t.a+'</b></div><div class="war2-center"><span>'+(live?'WAR ENDS IN':'MOBILIZATION')+'</span><b id="war-event-clock">'+(live?clock(state.endsAt-Date.now()):count+'/10 READY')+'</b></div><div class="war2-score team-b"><b>'+t.b+'</b><span>'+esc(state.teams.b.name)+'</span></div><nav><button onclick="openWarAchievements()"><i>✦</i><span>Honors</span></button><button onclick="openWarMatches()"><i>▶</i><span>Matches</span></button><button onclick="openWarRecord()"><i>≡</i><span>Record</span></button><button onclick="openWarArchive()"><i>▱</i><span>Archive</span></button></nav></header><section class="war2-map"><div class="war2-front front-a"></div><div class="war2-front front-b"></div><div class="war2-grid"></div>'+state.zones.map(objective).join('')+'</section>';}
function uiSnapshot(){const t=totals(),zones={};state.zones.forEach(z=>{const s=score(z);zones[z.id]={a:s.a,b:s.b,played:s.played,active:String(z.activeMatch?.matchId||'')};});return{a:t.a,b:t.b,matches:state.zones.reduce((n,z)=>n+score(z).played,0),zones};}
function uiDiff(next){const fx={zones:{},scoreA:false,scoreB:false,newDispatch:false};if(!lastUiSnapshot)return fx;fx.scoreA=next.a!==lastUiSnapshot.a;fx.scoreB=next.b!==lastUiSnapshot.b;fx.newDispatch=next.matches>lastUiSnapshot.matches;Object.keys(next.zones).forEach(id=>{const n=next.zones[id],p=lastUiSnapshot.zones[id]||{a:0,b:0,played:0,active:''};fx.zones[id]={star:n.played>p.played,score:n.a!==p.a||n.b!==p.b,started:!!n.active&&!p.active,ended:!n.active&&!!p.active};});return fx;}
function render(content){lifecycle();content=typeof resolveChRenderTarget==='function'?resolveChRenderTarget(content,'war'):content;if(!content)return;const next=uiSnapshot();renderFx=uiDiff(next);lastUiSnapshot=next;const mine=seat(me().uid),count=players().length,t=totals(),live=state.status==='active',motion=(renderFx.scoreA?' war2-score-a-updated':'')+(renderFx.scoreB?' war2-score-b-updated':'')+(renderFx.newDispatch?' war2-new-dispatch':'');if(mine)selectedTeam=mine.team;const post=lastWarAvailable()?state.lastResult:null,body=post?(postWarMap?finalTacticalMap(post):postWarSplash(post)):(warPage==='map'?tacticalMap(mine,count,t,live):briefing(mine,count,t,live)),page=post&&postWarMap?'map':warPage;content.innerHTML='<main class="challenger-war2 page-'+page+(post?' post-war-view':'')+motion+'">'+body+drawerHtml(mine)+'</main>';dot();tick();}
function rerender(){const p=document.querySelector('#ch-content > .ch-tab-pane[data-tab="war"]');if(p&&p.classList.contains('active'))render(p);dot();}
function dot(){const d=document.getElementById('ch-war-tab-dot');if(d)d.classList.toggle('live',state.status==='active');}
function tick(){if(ticker)clearInterval(ticker);ticker=setInterval(()=>{if(state.status!=='active')return;if(Date.now()>=state.endsAt||allComplete()){if(remoteEligible())pullRemoteState();else finish(allComplete()?'all-matchups':'timer',{remote:false});rerender();return;}const e=document.getElementById('war-event-clock');if(e)e.textContent=clock(state.endsAt-Date.now());},1000);}
window.openWarTacticalMap=()=>{warSfx('mapOpen','map-open',180);warPage='map';drawer='';rerender();};
window.viewLastWarMap=()=>{if(!lastWarAvailable())return;postWarMap=true;drawer='';warSfx('mapOpen','last-war-map',180);rerender();};
window.leaveLastWarMap=()=>{warSfx('mapClose','war-result-return',180);postWarMap=false;drawer='';rerender();};
