function resetSimulation(){let b=null;try{b=JSON.parse(localStorage.getItem(storageKey(SIMBACKUP))||'null');}catch(e){}if(!b){window.toast&&toast('No event simulation to reset.');return;}state=normalize(b.state)||fresh(1,[]);const p=profile();if(p&&b.profile)Object.keys(b.profile).forEach(k=>p[k]=clone(b.profile[k]));if(b.receipts==null){if(localStorage.removeItem)localStorage.removeItem(storageKey(RECEIPTS));else localStorage.setItem(storageKey(RECEIPTS),'{}');}else localStorage.setItem(storageKey(RECEIPTS),b.receipts);if(b.matchReceipts==null){if(localStorage.removeItem)localStorage.removeItem(storageKey(MATCH_RECEIPTS));else localStorage.setItem(storageKey(MATCH_RECEIPTS),'{}');}else localStorage.setItem(storageKey(MATCH_RECEIPTS),b.matchReceipts);if(localStorage.removeItem)localStorage.removeItem(storageKey(SIMBACKUP));else localStorage.setItem(storageKey(SIMBACKUP),'');drawer='';archiveCode='';selectedTeam=null;saveTestProfile();save({remote:false});pullRemoteState();window.toast&&toast('Event simulation and its rewards were reset.');rerender();}
async function runWarfrontServerCommand(action){
  try{
    const u=onlineIdentity();
    if(!u?.uid)throw new Error('Sign in before issuing a Warfront command.');
    const r=await window.FateOnline.flyApiRequest('/api/warfront/command',{method:'POST',body:{uid:u.uid,action}});
    const commanded=normalize(clone(r?.state));
    if(!commanded)throw new Error('Warfront command returned no usable event state.');
    state=commanded;
    try{localStorage.setItem(storageKey(KEY),JSON.stringify(state));}catch(e){}
    selectedMatchId='';selectedTeam=null;selectedZoneId='heartland';warPage='briefing';postWarMap=false;drawer='';archiveCode='';banSearch='';lastUiSnapshot=null;
    window.dispatchEvent(new CustomEvent('fate-war-event-updated',{detail:{state,remote:true,command:action}}));
    rerender();
    if(action==='deployment')window.toast&&toast('Fresh Warfront deployment phase started.');
    return true;
  }catch(e){window.toast&&toast(e?.message||'Warfront command failed.');await pullRemoteState();return false;}
}
